el('ros-export')?.addEventListener('click', () => {
  const list = loadReminders();
  const payload = JSON.stringify({ name: 'Run-of-Show', version: 1, steps: list.map(r => ({ text: r.text })) }, null, 2);
  const a = document.createElement('a');
  a.href = 'data:application/json;charset=utf-8,' + encodeURIComponent(payload);
  a.download = 'run-of-show.json';
  a.click();
});

el('ros-import-file')?.addEventListener('change', function () {
  const file = this.files && this.files[0]; if (!file) return;
  const reader = new FileReader();
  reader.onload = async (ev) => {
    try {
      const data = JSON.parse(ev.target.result);
      const steps = Array.isArray(data.steps) ? data.steps : (Array.isArray(data) ? data : null);
      if (!steps) { alert('Unrecognised format — expected { steps: [...] }.'); return; }
      const list = steps.map(s => ({ text: (typeof s === 'string' ? s : s.text || '').trim(), done: false })).filter(s => s.text);
      if (!list.length) { alert('No steps found in file.'); return; }
      const existing = loadReminders();
      if (existing.length && !(await appConfirm(`Replace ${existing.length} existing step(s) with ${list.length} imported step(s)?`, 'Replace'))) return;
      saveReminders(list); renderReminders();
    } catch { alert('Could not read file — make sure it is a valid Run-of-Show JSON.'); }
  };
  reader.readAsText(file);
  this.value = '';
});

renderReminders();

// ── Preview dock — renders overlay scenes directly (no OBS WebSocket needed) ─
const PV_SIZES = [480, 640, 820];
let _pvSizeIdx = 0;
function pvBaseUrl() { return 'http://127.0.0.1:3000'; }
function pvBuildOptions() {
  const sel = el('pv-scene'); if (!sel || sel.dataset.built) return;
  sel.dataset.built = '1';
  // First option = the live OBS PROGRAM (screenshot poll); the rest render overlays directly.
  sel.innerHTML = '<optgroup label="OBS"><option value="__obs__">◉ OBS Program (live)</option></optgroup>' +
    SCENE_SOURCES.map((g) =>
      `<optgroup label="${g.group}">` + g.items.map((it) => `<option value="${it.path}">${it.name}</option>`).join('') + '</optgroup>'
    ).join('');
}
let _pvObsTimer = null, _pvObsStream = null;
// Screenshot resolution follows the current (resizable) stage width, so it stays sharp when enlarged.
function pvStageW() { const s = el('pv-stage'); return s ? Math.min(960, Math.max(160, Math.round(s.clientWidth))) : (PV_SIZES[_pvSizeIdx] || 480); }
function pvObsStartScreenshots() {
  if (_pvObsTimer || _pvObsStream) return;   // don't poll while the smooth feed is live
  const poll = () => send('obs_screenshot', { width: pvStageW() });
  poll();
  _pvObsTimer = setInterval(poll, 800);
}
// Full stop — used when leaving OBS mode / closing the dock.
function pvStopObs() {
  if (_pvObsTimer) { clearInterval(_pvObsTimer); _pvObsTimer = null; }
  if (_pvObsStream) { _pvObsStream.getTracks().forEach((t) => t.stop()); _pvObsStream = null; }
  const v = el('pv-obs-video'); if (v) { v.srcObject = null; v.style.display = 'none'; }
  const lb = el('pv-obs-live'); if (lb) { lb.classList.remove('on'); lb.style.display = 'none'; }
}
// Both were deleted with the old switcher panel while their callers stayed: swBackend's callers are
// typeof-guarded, so vMix producers were silently checked against OBS; SW_VCAM_RE threw outright,
// so the live OBS preview never found the virtual camera.
function swBackend(data) { return (data && data.switcher && data.switcher.target) === 'vmix' ? 'vmix' : 'obs'; }
const SW_VCAM_RE = /obs\s*virtual|obs-camera|obs cam|vmix|virtual cam/i;
// Smooth live OBS feed via the Virtual Camera (getUserMedia). Auto-starts OBS's virtual cam first.
async function pvObsLiveStart(silent) {
  const lb = el('pv-obs-live'), v = el('pv-obs-video'), img = el('pv-obs-img'), msg = el('pv-obs-msg');
  try {
    send('obs_virtualcam', { on: true });   // make sure OBS's virtual camera is running
    let cams = (await navigator.mediaDevices.enumerateDevices()).filter((d) => d.kind === 'videoinput');
    if (!cams.some((d) => d.label)) {
      if (silent) return false;   // labels hidden until permission granted — never prompt silently
      const unlock = await navigator.mediaDevices.getUserMedia({ video: true, audio: false });
      unlock.getTracks().forEach((t) => t.stop());
      cams = (await navigator.mediaDevices.enumerateDevices()).filter((d) => d.kind === 'videoinput');
    }
    let vcam = cams.find((d) => SW_VCAM_RE.test(d.label || ''));
    if (!vcam && !silent) {   // OBS may have just started the vcam — give the device a beat to appear
      await new Promise((r) => setTimeout(r, 900));
      cams = (await navigator.mediaDevices.enumerateDevices()).filter((d) => d.kind === 'videoinput');
      vcam = cams.find((d) => SW_VCAM_RE.test(d.label || ''));
    }
    if (!vcam) { if (!silent && msg) { msg.textContent = 'Starting OBS Virtual Camera — give it a second, then click Smooth again.'; msg.style.display = 'flex'; } return false; }
    const stream = await navigator.mediaDevices.getUserMedia({ video: { deviceId: { exact: vcam.deviceId } }, audio: false });
    _pvObsStream = stream;
    if (_pvObsTimer) { clearInterval(_pvObsTimer); _pvObsTimer = null; }   // stop screenshot polling
    if (v) { v.srcObject = stream; v.style.display = ''; }
    if (img) img.style.display = 'none';
    if (msg) msg.style.display = 'none';
    if (lb) lb.classList.add('on');
    return true;
  } catch (e) {
    if (!silent && msg) { msg.textContent = 'Live feed error: ' + (e.name || e.message); msg.style.display = 'flex'; }
    pvObsLiveStop();
    return false;
  }
}
function pvObsLiveStop() {
  if (_pvObsStream) { _pvObsStream.getTracks().forEach((t) => t.stop()); _pvObsStream = null; }
  const v = el('pv-obs-video'); if (v) { v.srcObject = null; v.style.display = 'none'; }
  const lb = el('pv-obs-live'); if (lb) lb.classList.remove('on');
  if (el('pv-scene')?.value === '__obs__') pvObsStartScreenshots();   // fall back to screenshots
}
function pvLoad() {
  const sel = el('pv-scene'), frame = el('pv-frame'), img = el('pv-obs-img'), msg = el('pv-obs-msg');
  if (!sel || !frame) return;
  if (sel.value === '__obs__') {
    // OBS Program mode — start OBS's Virtual Camera, poll a JPEG of the live program (works with no
    // camera permission), and offer the "Smooth" button for a low-latency getUserMedia feed.
    pvStopObs();   // clean slate: clears any prior timer/stream and hides the video + button
    frame.style.display = 'none';
    if (img) img.style.display = '';
    const lb = el('pv-obs-live'); if (lb) { lb.style.display = ''; lb.classList.remove('on'); }
    send('obs_virtualcam', { on: true });   // START VIRTUAL CAM WHEN NOT ACTIVE
    pvObsStartScreenshots();
    if (typeof showToast === 'function') showToast('OBS Program preview — Virtual Camera started. Click "Smooth" for a live feed.', '#22c55e', 2600);
    return;
  }
  pvStopObs();
  if (img) img.style.display = 'none';
  if (msg) msg.style.display = 'none';
  frame.style.display = '';
  let url = pvBaseUrl() + (sel.value || '/');
  if (el('pv-sample')?.checked) url += (url.includes('?') ? '&' : '?') + 'preview=1';
  frame.src = url;
}
function applyObsScreenshot(d) {
  if (el('pv-scene')?.value !== '__obs__' || _pvObsStream) return;   // ignore while the smooth feed is live
  const img = el('pv-obs-img'), msg = el('pv-obs-msg');
  if (d && d.ok && d.img) {
    if (img) { img.src = d.img; img.style.display = ''; }
    if (msg) msg.style.display = 'none';
  } else {
    if (img) img.style.display = 'none';
    if (msg) { msg.textContent = (d && d.reason) === 'OBS not connected' ? 'OBS is not connected. Connect it under Apps > Streaming software, then reopen this preview.' : ((d && d.reason) || 'OBS not connected'); msg.style.display = 'flex'; }
  }
}
el('btn-preview')?.addEventListener('click', () => {
  const dock = el('preview-dock'); if (!dock) return;
  const show = dock.style.display === 'none';
  dock.style.display = show ? 'block' : 'none';
  if (show) { pvBuildOptions(); if (!el('pv-frame').src && el('pv-scene')?.value !== '__obs__') pvLoad(); }
  else { pvStopObs(); const f = el('pv-frame'); if (f && f.src) f.removeAttribute('src'); }   // stop the background overlay too
});
el('pv-close')?.addEventListener('click', () => { el('preview-dock').style.display = 'none'; pvStopObs(); const f = el('pv-frame'); if (f && f.src) f.removeAttribute('src'); });
el('pv-scene')?.addEventListener('change', pvLoad);
el('pv-sample')?.addEventListener('change', pvLoad);
el('pv-reload')?.addEventListener('click', pvLoad);
el('pv-popout')?.addEventListener('click', () => {
  const sel = el('pv-scene');
  // resizable=yes → the popped-out preview window can be dragged to any size.
  window.open(pvBaseUrl() + (sel?.value || '/'), 'ne-preview', 'width=960,height=540,resizable=yes,scrollbars=no');
});
el('pv-obs-live')?.addEventListener('click', () => { if (_pvObsStream) pvObsLiveStop(); else pvObsLiveStart(false); });
el('pv-size')?.addEventListener('click', () => {
  _pvSizeIdx = (_pvSizeIdx + 1) % PV_SIZES.length;
  const stage = el('pv-stage'); if (stage) stage.style.width = PV_SIZES[_pvSizeIdx] + 'px';   // inline so it cooperates with drag-resize
  document.documentElement.style.setProperty('--pv-w', PV_SIZES[_pvSizeIdx] + 'px');
});
// Drag-to-resize the stage (CSS resize:horizontal) → keep the scaled iframe/screenshot in sync.
(function pvWireResize() {
  const stage = el('pv-stage'); if (!stage || typeof ResizeObserver === 'undefined') return;
  const ro = new ResizeObserver(() => {
    const w = Math.round(stage.clientWidth); if (w > 0) document.documentElement.style.setProperty('--pv-w', w + 'px');
  });
  ro.observe(stage);
})();

// ── Dashboard: Player Cams (link a cam URL to each active player) ───────────
let _playerCamsSig = '';
function renderPlayerCams(data) {
  const wrap = el('player-cams-rows');
  if (!wrap) return;
  const teams = data.teams || {};
  const colorOf = (s) => (teams[s] && teams[s].color) || (s === 'blue' ? '#055fdb' : '#e97139');

  // Roster (start.gg names) by side — used to label live players + as the pre-game fallback.
  const roster = [];
  ['blue', 'orange'].forEach((side) => {
    ((teams[side] && teams[side].players) || []).forEach((p) => {
      if (p && p.name) roster.push({ side, name: p.name, id: p.platformId || p.primaryid || null });
    });
  });

  // Live in-game players — the actual lineup, WITH their side. Only these get cam rows during a match.
  const live = [];
  (data.players || []).forEach((p) => { if (p && p.name) live.push({ name: p.name, id: p.primaryid || null, side: Number(p.team) === 1 ? 'orange' : 'blue' }); });
  ((data.csgo && data.csgo.players) || []).forEach((p) => { if (p && p.name) live.push({ name: p.name, id: p.steamid || null, side: p.team === 'T' ? 'orange' : 'blue' }); });

  // Facecam lookups (the shared store — same as the Facecams tab).
  const camByName = {}, camById = {};
  (data.facecams || []).forEach((f) => { if (!f) return; if (f.name) camByName[f.name.toLowerCase()] = f.link || ''; if (f.platformId) camById[String(f.platformId)] = f.link || ''; });
  const camFor = (name, id) => (id && camById[String(id)]) || (name && camByName[name.toLowerCase()]) || '';

  const fuzzy = (a, b) => { a = (a || '').toLowerCase(); b = (b || '').toLowerCase(); return !!a && !!b && (a === b || a.includes(b) || b.includes(a)); };
  // Reverse-match a live player to a roster (start.gg) name for context.
  const startggFor = (lp) =>
    (roster.find((r) => r.id && lp.id && String(r.id) === String(lp.id))
      || roster.find((r) => r.name.toLowerCase() === lp.name.toLowerCase())
      || roster.find((r) => fuzzy(r.name, lp.name)) || {}).name || '';

  const liveMode = live.length > 0;
  // Rows = the in-game lineup (per side) when a match is live; otherwise the roster (pre-game setup).
  const rows = liveMode
    ? live.map((lp) => ({ ingame: lp.name, startgg: startggFor(lp), side: lp.side, id: lp.id }))
    : roster.map((r) => ({ ingame: '', startgg: r.name, side: r.side, id: r.id }));

  const teamSig = ['blue', 'orange'].map((s) => (teams[s] && (teams[s].name + '|' + teams[s].color)) || '');
  const sig = JSON.stringify({ rows, camByName, camById, liveMode, teamSig });
  if (sig === _playerCamsSig) return;
  if (wrap.contains(document.activeElement)) return;   // don't clobber a field being edited
  _playerCamsSig = sig;
  wrap.innerHTML = '';

  if (liveMode) {
    const ref = document.createElement('div');
    ref.className = 'pcam-live-ref';
    ref.innerHTML = '<span class="pcam-live-label">In game now</span>';
    live.forEach((l) => { const c = document.createElement('span'); c.className = 'pcam-live-chip'; c.style.borderLeft = `3px solid ${colorOf(l.side)}`; c.textContent = l.name; ref.appendChild(c); });
    wrap.appendChild(ref);
    const dl = document.createElement('datalist'); dl.id = 'pcam-live-list';
    live.forEach((l) => { const o = document.createElement('option'); o.value = l.name; dl.appendChild(o); });
    wrap.appendChild(dl);
  }

  if (!rows.length) {
    const p = document.createElement('p');
    p.style.cssText = 'font-size:12px; color:var(--muted);';
    p.textContent = 'Add teams & players first (Teams tab) — active players appear here.';
    wrap.appendChild(p);
    return;
  }

  // Team names/labels for the group headers (real team name → game side label → generic).
  const g = (data.games && data.activeGame) ? data.games[data.activeGame] : null;
  const sideLabels = (g && g.teamLabels) || { a: 'Blue', b: 'Orange' };
  const teamNameOf = (side) => (teams[side] && (teams[side].name || '').trim())
    || (side === 'blue' ? sideLabels.a : sideLabels.b)
    || (side === 'blue' ? 'Blue Team' : 'Orange Team');

  function makeCamRow(row) {
    const key = row.ingame || row.startgg;
    const existing = camFor(key, row.id) || (row.startgg && camByName[row.startgg.toLowerCase()]) || '';

    const div = document.createElement('div');
    div.className = 'pcam-row';
    div.innerHTML = `
      <span class="pcam-side"></span>
      <div class="pcam-names">
        <span class="pcam-name"></span>
        ${liveMode
          ? '<span class="pcam-sub"></span>'
          : '<input type="text" class="input-text pcam-ingame" list="pcam-live-list" autocomplete="off" placeholder="in-game name" title="The name the overlay matches this cam to">'}
      </div>
      <input type="text" class="input-text pcam-url" placeholder="https://vdo.ninja/?view=…">
      <button class="btn btn-secondary btn-sm pcam-apply">Apply</button>`;
    div.querySelector('.pcam-side').style.background = colorOf(row.side);
    div.querySelector('.pcam-name').textContent = liveMode ? row.ingame : row.startgg;
    const urlInput = div.querySelector('.pcam-url');
    urlInput.value = existing;

    if (liveMode) {
      const sub = div.querySelector('.pcam-sub');
      if (sub) sub.textContent = row.startgg ? `start.gg: ${row.startgg}` : 'no start.gg match';
    } else {
      // Pre-game: editable in-game name; picking/typing one that has a saved cam fills the URL.
      const ig = div.querySelector('.pcam-ingame');
      ig.addEventListener('input', () => { const u = camFor(ig.value.trim(), row.id); if (u) urlInput.value = u; });
    }

    const btn = div.querySelector('.pcam-apply');
    btn.addEventListener('click', () => {
      const camKey = liveMode ? row.ingame : (div.querySelector('.pcam-ingame')?.value.trim() || row.startgg);
      send('save_facecam', { name: camKey, platform: 'bot', platformId: row.id || null, link: urlInput.value.trim() });
      btn.textContent = 'Saved'; setTimeout(() => { btn.textContent = 'Apply'; }, 1000);
    });
    return div;
  }

  // Group rows under a team header (team name in the team's colour) instead of a bare blue/orange bar.
  ['blue', 'orange'].forEach((side) => {
    const sideRows = rows.filter((r) => r.side === side);
    if (!sideRows.length) return;
    const color = colorOf(side);
    const head = document.createElement('div');
    head.className = 'pcam-team-head';
    head.style.borderLeft = `4px solid ${color}`;
    head.innerHTML = `<span class="pcam-team-dot"></span><span class="pcam-team-name"></span><span class="pcam-team-count"></span>`;
    head.querySelector('.pcam-team-dot').style.background = color;
    head.querySelector('.pcam-team-name').textContent = teamNameOf(side);
    head.querySelector('.pcam-team-name').style.color = color;
    head.querySelector('.pcam-team-count').textContent = `${sideRows.length} ${sideRows.length === 1 ? 'player' : 'players'}`;
    wrap.appendChild(head);
    sideRows.forEach((row) => wrap.appendChild(makeCamRow(row)));
  });
}
document.querySelectorAll('.js-goto-facecams').forEach((b) => b.addEventListener('click', () => {
  document.querySelector('.tab-btn[data-tab="produccion"]')?.click();
  if (typeof window._pdShow === 'function') window._pdShow('cameras');
}));
document.querySelectorAll('.js-goto-scenes').forEach((b) => b.addEventListener('click', () => {
  document.querySelector('.tab-btn[data-tab="media"]')?.click();
  if (typeof window._assetsShow === 'function') window._assetsShow('overlays');
}));

// ── Camera Feeds / VDO talent domain (cf*, vdo*) — extracted to camera-feeds.js ──
function tlEsc(s) { return esc(s); }   // legacy alias — canonical esc() lives in core.js; kept in app.js (used across app.js + spotlight.js)

// Control panel, part 10 of 17: Dashboard: stream queue, desk show, brackets, connected event, upcoming and standings, presets.
// Built into control-panel/app.js with the other parts (scripts/build-panel-app.js): one script, one scope.

// ── Dashboard: start.gg stream queue ────────────────────────────────────────
let _sggQueueSig = '';
let _sggStreamHintKey = '';   // event the hint currently refers to (used by the Follow-all button)
// Nudge the producer to pick which stream/station they're producing when a start.gg event runs several.
// This used to be a modal that popped over the whole app on load; it's now an inline line inside the
// event panel, right under the #sgg-stream selector, so loading an event never interrupts anything.
// Picking a station scopes the queue/ticker/schedule + auto-follow to it; "Follow all" is an explicit
// choice, localStorage-gated per event so it stays dismissed on later launches.
function renderStreamFollowHint(streams, evKey, picked) {
  const hint = el('sgg-stream-hint'); if (!hint) return;
  let dismissed = false;
  try { dismissed = !!(evKey && localStorage.getItem('sgg_stream_picked::' + evKey)); } catch (_) {}
  if (picked || dismissed || !evKey || (streams || []).length < 2) { hint.style.display = 'none'; return; }
  hint.style.display = '';
  const msg = el('sgg-stream-hint-msg');
  if (msg) msg.textContent = `This event runs ${streams.length} streams — pick yours above so the queue, ticker, schedule and auto-follow only use that station.`;
}
// "Follow all" is the one action the hint offers; the stations themselves are picked in the selector.
el('sgg-stream-hint-all')?.addEventListener('click', () => {
  const evKey = _sggStreamHintKey;
  try { if (evKey) localStorage.setItem('sgg_stream_picked::' + evKey, '1'); } catch (_) {}
  const sel = el('sgg-stream'); if (sel) sel.value = '';
  const hint = el('sgg-stream-hint'); if (hint) hint.style.display = 'none';
  send('startgg_set_autofollow', { enabled: !!el('sgg-autofollow')?.checked, streamName: '' });
  if (typeof showToast === 'function') showToast('Following all streams');
});
// Two "you are not being moved" states, both deliberately visible: the producer's station has
// dropped off start.gg's queue and is being held from cache (never swapped for another station),
// and auto-follow parking on the match that is already on air instead of jumping to the next one.
function renderStationNote(sg) {
  const note = el('sgg-stream-note'); if (!note) return;
  const hold = sg.autoFollowHold;
  const lines = [];
  if (sg.streamOffQueue && sg.streamName) {
    lines.push(`No sets on "${sg.streamName}" right now — holding your station. Nothing from another stream will be pushed.`);
  }
  if (hold && hold.setId) {
    const q = (sg.queue || []);
    const nxt = q.find((x) => String(x.setId) === String(hold.nextSetId));
    const who = nxt ? `${nxt.teamA || 'TBD'} vs ${nxt.teamB || 'TBD'}` : 'the next match';
    lines.push(`Auto-follow is holding the match on air — ${who} is waiting. Push it yourself to switch now.`);
  }
  note.textContent = lines.join(' ');
  note.style.display = lines.length ? '' : 'none';
}
function renderStreamQueue(data) {
  const sg = data.startgg || {};
  const tEl = el('sgg-tournament');
  if (tEl && document.activeElement !== tEl) {
    tEl.value = sg.tournamentSlug || el('input-startgg-tournament')?.value || '';
  }
  const qOn = el('sgg-queue-enabled');
  if (qOn && document.activeElement !== qOn) qOn.checked = !!sg.queueEnabled;
  const af = el('sgg-autofollow'); if (af && document.activeElement !== af) af.checked = !!sg.autoFollow;
  // Once the event is connected the queue polls automatically — the manual Queue toggle is redundant,
  // so hide it (leaving just Auto-follow). Still shown pre-connection as an escape hatch.
  const qToggle = el('sgg-queue-toggle');
  if (qToggle) qToggle.style.display = sg.connected ? 'none' : '';
  // Same for the slug box + Load Queue button: once connected the slug is already known and
  // the queue refreshes on its own, so the row is dead space. Shown again if we disconnect.
  const slugRow = el('sgg-slug-row');
  if (slugRow) slugRow.style.display = sg.connected ? 'none' : 'flex';
  const status = el('sgg-status');
  if (status) {
    if (sg.connected && sg.queueFetchedAt) {
      status.textContent = `Connected · ${(sg.queue || []).length} queued set(s) · updated ${new Date(sg.queueFetchedAt).toLocaleTimeString()}`;
      status.style.color = '#9ae6b4';
    } else if (sg.lastError) {
      status.textContent = sg.lastError;
      status.style.color = '#f56565';
    } else if (sg.queueEnabled) {
      status.textContent = 'Polling stream queue…';
      status.style.color = 'var(--muted)';
    } else {
      status.textContent = 'Stream queue off. Add your token and tournament under Apps > start.gg, then turn it on.';
      status.style.color = 'var(--muted)';
    }
  }

  const streams = sg.streams || [];
  const streamRow = el('sgg-stream-row');
  const streamSel = el('sgg-stream');
  // Show the picker as soon as the tournament has ANY stream, not just when it has several. On a
  // multi-station championship the producer needs to pin their station before their stream has a
  // set queued on it — waiting until streams.length > 1 hid the control exactly when it mattered.
  if (streamRow) streamRow.style.display = (streams.length || sg.streamName) ? '' : 'none';

  const queue = sg.queue || [];
  const sig = JSON.stringify({ queue, streams, sel: streamSel && streamSel.value, pushed: sg.lastPushedSetId, off: !!sg.streamOffQueue, hold: sg.autoFollowHold || null });
  if (sig === _sggQueueSig) return;
  _sggQueueSig = sig;

  if (streamSel) {
    const cur = streamSel.value;
    // An explicit "All streams" entry: following every station is a deliberate choice, not the
    // accident you get when a station name fails to match. And the station we're ON is always an
    // option, even if this poll's queue didn't list it (the server pins it too — belt and braces):
    // rebuilding the list without it silently reset the selector to "All streams" the moment a
    // station ran out of queued sets, which is exactly when a producer must NOT be moved off it.
    const pinned = cur || sg.streamName || '';
    const opts = pinned && !streams.includes(pinned) ? [...streams, pinned] : streams;
    streamSel.innerHTML = '<option value="">All streams</option>'
      + opts.map((s) => `<option value="${_stEsc(s)}">${_stEsc(s)}</option>`).join('');
    if (opts.includes(cur)) streamSel.value = cur;
    else if (sg.streamName && opts.includes(sg.streamName)) streamSel.value = sg.streamName;
    else if (!cur) streamSel.value = '';
  }
  // Nudge the producer to pick their stream when the event runs several and none is chosen — inline
  // in this panel, never a popup (localStorage stops "Follow all" nagging every launch).
  const _evKey = (sg.tournamentSlug || '') + '|' + (sg.eventSlug || '');
  _sggStreamHintKey = _evKey;
  renderStreamFollowHint(streams, _evKey, !!sg.streamName);
  renderStationNote(sg);
  const wantStream = (streamSel && streamSel.value) || '';
  const wrap = el('sgg-queue'); if (!wrap) return;
  // Once a station is picked the list shows THAT station only — previously a single-stream
  // tournament ignored the filter entirely (streams.length <= 1), which was fine, but the same
  // clause meant the filter silently did nothing in the case it was written for.
  const rows = queue.filter((s) => !wantStream || s.stream === wantStream);
  wrap.innerHTML = '';
  const teamLogos = {};
  (data.savedTeams || []).forEach((t) => { if (t && t.name && t.logo) teamLogos[t.name.toLowerCase()] = t.logo; });
  const logoFor = (name, fallback) => fallback || teamLogos[(name || '').toLowerCase()] || '';
  const sideHtml = (name, logo) => {
    const l = logoFor(name, logo);
    return `<span class="sgg-team">${l ? `<img class="sgg-logo" src="${l}" onerror="this.style.display='none'">` : ''}<b></b></span>`;
  };
  rows.forEach((s) => {
    const row = document.createElement('div');
    // Green = start.gg has the set IN PROGRESS. The set merely sitting at the head of the stream
    // queue is "ON DECK" — cued up, not called. (Before, head-of-queue was painted LIVE, so a
    // semi-final showed green the moment the quarter-finals cleared off the queue.)
    const onDeck = !s.live && s.state !== 3 && s.onStream;
    row.className = 'sgg-row' + (s.live ? ' live' : (onDeck ? ' ondeck' : ''));
    const badge = s.live ? 'LIVE' : (s.state === 3 ? 'DONE' : (onDeck ? 'ON DECK' : 'NEXT'));
    const onOverlay = s.setId === sg.lastPushedSetId;
    const score = (s.scoreA != null || s.scoreB != null) ? `<span class="sgg-score">${s.scoreA ?? 0}–${s.scoreB ?? 0}</span>` : '';
    row.innerHTML = `
      <span class="sgg-badge">${badge}</span>
      <span class="sgg-match">${sideHtml(s.teamA, s.logoA)} <span class="sgg-vs">vs</span> ${sideHtml(s.teamB, s.logoB)}${score}<span class="sgg-round"></span></span>
      <button class="btn btn-secondary btn-sm sgg-push"></button>`;
    const bolds = row.querySelectorAll('.sgg-team b');
    bolds[0].textContent = s.teamA; bolds[1].textContent = s.teamB;
    row.querySelector('.sgg-round').textContent = s.round || '';
    const btn = row.querySelector('.sgg-push');
    btn.textContent = onOverlay ? 'On overlay' : 'Push';
    btn.addEventListener('click', async () => { if (await confirmQueuePush()) send('startgg_push_set', { setId: s.setId }); });
    wrap.appendChild(row);
  });
}
function _sggShowTab(which) {
  const tabs = { queue: 'sgg-tab-queue', team: 'sgg-tab-team', archive: 'sgg-tab-archive' };
  Object.entries(tabs).forEach(([k, id]) => el(id)?.classList.toggle('is-on', k === which));
  if (el('sgg-queue-wrap')) el('sgg-queue-wrap').style.display = which === 'queue' ? '' : 'none';
  if (el('sgg-team-wrap')) el('sgg-team-wrap').style.display = which === 'team' ? '' : 'none';
  if (el('sgg-archive-wrap')) el('sgg-archive-wrap').style.display = which === 'archive' ? '' : 'none';
  // Auto-follow / Queue toggles drive the LIVE queue — hide them on the read-only Archive.
  if (el('sgg-queue-toggles')) el('sgg-queue-toggles').style.display = which === 'archive' ? 'none' : '';
}
el('sgg-tab-queue')?.addEventListener('click', () => {
  _sggShowTab('queue');
  send('startgg_set_upcoming_mode', { mode: 'event' });   // upcoming/schedule board follows the stream queue
});
el('sgg-tab-team')?.addEventListener('click', () => {
  _sggShowTab('team');
  send('startgg_set_upcoming_mode', { mode: 'team' });   // upcoming/schedule board follows the searched team
  refreshSggTeamPicker();
});
el('sgg-tab-archive')?.addEventListener('click', () => {
  _sggShowTab('archive');
  renderStreamArchive(currentState || {});
});
// Post-event review: the matches that played / were on air on the followed stream this event, newest
// first. Read-only apart from a Re-push button to put one back on the scoreboard.
function renderStreamArchive(data) {
  const wrap = el('sgg-archive'); if (!wrap) return;
  const sg = (data || currentState || {}).startgg || {};
  const arch = (Array.isArray(sg.queueArchive) ? sg.queueArchive.slice() : []).sort((a, b) => (b.ts || 0) - (a.ts || 0));
  if (!arch.length) {
    wrap.innerHTML = '<div style="font-size:12px;color:var(--muted);padding:8px 2px;">No matches archived yet — sets you broadcast this event collect here.</div>';
    return;
  }
  const teamLogos = {};
  ((data || {}).savedTeams || (currentState || {}).savedTeams || []).forEach((t) => { if (t && t.name && t.logo) teamLogos[t.name.toLowerCase()] = t.logo; });
  const logoFor = (name) => teamLogos[(name || '').toLowerCase()] || '';
  const sideHtml = (name) => { const l = logoFor(name); return `<span class="sgg-team">${l ? `<img class="sgg-logo" src="${l}" onerror="this.style.display='none'">` : ''}<b></b></span>`; };
  wrap.innerHTML = '';
  arch.forEach((s) => {
    const row = document.createElement('div');
    row.className = 'sgg-row' + (s.done ? '' : ' ondeck');
    const badge = s.done ? 'DONE' : 'ON AIR';
    const score = (s.scoreA != null || s.scoreB != null) ? `<span class="sgg-score">${s.scoreA ?? 0}–${s.scoreB ?? 0}</span>` : '';
    const when = s.ts ? new Date(s.ts).toLocaleTimeString() : '';
    row.innerHTML = `
      <span class="sgg-badge">${badge}</span>
      <span class="sgg-match">${sideHtml(s.teamA)} <span class="sgg-vs">vs</span> ${sideHtml(s.teamB)}${score}<span class="sgg-round"></span></span>
      <button class="btn btn-secondary btn-sm sgg-push">Re-push</button>`;
    const bolds = row.querySelectorAll('.sgg-team b');
    bolds[0].textContent = s.teamA; bolds[1].textContent = s.teamB;
    row.querySelector('.sgg-round').textContent = [s.round, s.stream, when].filter(Boolean).join(' · ');
    row.querySelector('.sgg-push').addEventListener('click', async () => { if (await confirmQueuePush()) send('startgg_push_set', { setId: s.setId }); });
    wrap.appendChild(row);
  });
}

// Logo-carrying team picker for the Stream Queue → Team search (same searchable component as the
// Match team / brand-kit pickers, so producers see logos instead of a plain text datalist).
let _sggPickedTeam = '';
let _sggPickerSig = '';
function refreshSggTeamPicker(force) {
  const mount = el('sgg-team-pick');
  if (!mount || typeof buildSearchPicker !== 'function') return;
  const teams = allMatchTeams();
  const sig = teams.map((t) => (t.name || '') + '|' + (t.logo ? '1' : '0')).join('~');
  if (!force && sig === _sggPickerSig && mount.firstChild) return;
  _sggPickerSig = sig;
  const items = teams.map((t) => ({ value: t.name, label: t.name, img: t.logo || '../assets/rl.png' }));
  mount.innerHTML = '';
  mount.appendChild(buildSearchPicker({
    items, value: _sggPickedTeam, placeholder: 'Search team…', emptyLabel: '— Clear —',
    className: 'sgg-team-pick',
    onPick: (name) => {
      _sggPickedTeam = name || '';
      if (!name) return;
      const st = el('sgg-status');
      if (st) { st.textContent = 'Searching…'; st.style.color = 'var(--muted)'; }
      send('startgg_fetch_team_queue', { teamName: name });
    },
  }));
}
el('sgg-team-search')?.addEventListener('click', () => {
  const name = (_sggPickedTeam || '').trim();
  const st = el('sgg-status');
  if (!name) { if (st) { st.textContent = 'Pick a team first.'; st.style.color = '#f56565'; } return; }
  if (st) { st.textContent = 'Searching...'; st.style.color = 'var(--muted)'; }
  send('startgg_fetch_team_queue', { teamName: name });
});
el('sgg-load')?.addEventListener('click', () => send('startgg_fetch_queue', { tournamentSlug: (el('sgg-tournament')?.value || '').trim() }));
el('sgg-queue-enabled')?.addEventListener('change', function () {
  send('startgg_set_queue', { enabled: this.checked });
});
el('sgg-autofollow')?.addEventListener('change', function () {
  send('startgg_set_autofollow', { enabled: this.checked, streamName: el('sgg-stream')?.value || '' });
});
el('sgg-stream')?.addEventListener('change', function () {
  _sggQueueSig = '';
  // Picking from the selector IS the answer to the inline nudge — dismiss it now (and for good on
  // this event) rather than waiting for the next state round-trip.
  try { if (_sggStreamHintKey) localStorage.setItem('sgg_stream_picked::' + _sggStreamHintKey, '1'); } catch (_) {}
  const _hint = el('sgg-stream-hint'); if (_hint) _hint.style.display = 'none';
  // ALWAYS tell the server which station we're on — not only while auto-follow is armed. The
  // server uses streamName for the ticker scope and for Autofill Teams too, and producers pick
  // their station during setup, before arming auto-follow. Passing the switch's current value
  // keeps this a stream change, not an auto-follow change.
  send('startgg_set_autofollow', { enabled: !!el('sgg-autofollow')?.checked, streamName: this.value });
  const st = el('sgg-status');
  if (st) {
    st.textContent = this.value ? `Following "${this.value}" — queue and auto-follow ignore other streams.` : 'Following all streams.';
    st.style.color = 'var(--muted)';
  }
});

