  const og = el('obs-fields-grid'); if (og) og.style.display = slobs ? 'none' : 'grid';
  const oh = el('obs-fields-help'); if (oh) oh.style.display = slobs ? 'none' : '';
  // A scene collection file is imported by OBS only.
