    if (hdrListen) {
      const liS = currentState.listenIn || {};
      const on = liS.active && liS.scope === 'room' && liS.side === hdrListen.dataset.side;
      if (on) send('clear_listen_in'); else send('set_listen_in', { side: hdrListen.dataset.side });
      return;
    }
